action.code:
if (open_list.empty())
    return nullptr;

auto min_it = open_list.begin();
float min_f = (*min_it)->g_value + (*min_it)->h_value;

for (auto it = open_list.begin() + 1; it != open_list.end(); ++it) {
    float f = (*it)->g_value + (*it)->h_value;
    if (f < min_f) {
        min_f = f;
        min_it = it;
    }
}

Node* best_node = *min_it;
open_list.erase(min_it);
return best_node;

